import json,pathlib
M={
'Overall':[('Construction production',25,'Eurostat sts_copr_m F','construction_production','live'),('Civil engineering output',20,'Eurostat sts_copr_m F42','civil_output','live'),('Building permits',15,'Eurostat permits','permits','pending'),('Construction confidence',15,'EC BCS','confidence','pending'),('Construction employment',10,'Eurostat STS','employment','pending'),('Construction prices & costs',10,'Eurostat STS','costs','pending'),('Fixed investment',5,'Eurostat National Accounts','investment','pending')],
'Transportation':[('Civil engineering output',25,'Eurostat sts_copr_m F42','civil_output','live'),('Transport investment & pipeline',25,'TEN-T / CEF','transport_pipeline','pending'),('Rail freight activity',15,'Eurostat Transport','rail','pending'),('Road freight activity',10,'Eurostat Transport','road','pending'),('Ports & logistics',10,'Eurostat Maritime','ports','pending'),('Construction confidence',10,'EC BCS','confidence','pending'),('Funding announcements',5,'EIB / EBRD','transport_funding','pending')],
'Site Development':[('Building permits',30,'Eurostat','permits','pending'),('Non-residential permits',20,'Eurostat','nonres_permits','pending'),('Building construction output',20,'Eurostat sts_copr_m F41','building_output','live'),('Construction confidence',10,'EC BCS','confidence','pending'),('Construction employment',10,'Eurostat STS','employment','pending'),('Financing & property conditions',10,'Eurostat / ECB','financing','pending')],
'Waste & Water':[('Wastewater treatment connection',15,'World Bank / Eurostat Water','drinking_water','live'),('Water stress & abstraction',15,'World Bank / EEA','water_stress','live'),('Waste generation & treatment',15,'Eurostat Waste','waste','pending'),('Water infrastructure funding',20,'EIB','water_funding','pending'),('Treatment & reservoir pipeline',20,'EIB / EBRD','water_pipeline','pending'),('Landfill & remediation pipeline',15,'EIB / EBRD','remediation','pending')],
'Oil & Gas':[('Oil & gas extraction index',20,'Eurostat / World Bank','oil_rents','live'),('Crude & gas production',15,'World Bank / Eurostat','gas_rents','live'),('Refinery throughput',10,'Eurostat Energy','refinery','pending'),('LNG imports & terminal use',15,'Eurostat Energy','lng','pending'),('Pipeline, storage & terminal projects',30,'EIB / EBRD','oil_pipeline','pending'),('Asset approvals & regulation',10,'Official regulators','approvals','pending')],
'Mining':[('Mining & quarrying production',20,'Eurostat / World Bank','mineral_rents','live'),('Metal ore production',15,'National statistics','ore','pending'),('Mining investment & capex',20,'EBRD','mining_capex','pending'),('Mine approvals & pipeline',20,'National authorities','mine_pipeline','pending'),('Tailings & remediation projects',15,'EIB / EBRD','tailings','pending'),('Commodity-price context',10,'World Bank Pink Sheet','metals','pending')],
'Renewables':[('Renewable capacity additions',20,'IRENA / World Bank','renewable_share','live'),('Renewable generation',15,'ENTSO-E / World Bank','renewable_electricity','live'),('Auctions & awarded projects',20,'National auctions / EIB','renewable_awards','pending'),('Permitted project pipeline',20,'National regulators','renewable_pipeline','pending'),('Grid investment',15,'ENTSO-E / EIB','grid','pending'),('Battery storage pipeline',10,'National regulators / EIB','storage','pending')],
'Agriculture':[('Drought & soil moisture',25,'Copernicus','drought','pending'),('Agricultural investment',20,'Eurostat Agriculture','agri_growth','live'),('Irrigation & water programmes',15,'EIB','irrigation','pending'),('Crop & livestock outlook',15,'Eurostat Agriculture','agri_share','live'),('Agricultural output prices',10,'Eurostat Agriculture','agri_prices','pending'),('Input costs',10,'Eurostat Agriculture','input_costs','pending'),('CAP & rural development funding',5,'EU / EIB','cap','pending')]}
urls={'Eurostat':'https://ec.europa.eu/eurostat/databrowser/','World Bank':'https://data.worldbank.org/','EIB':'https://www.eib.org/en/projects/index.htm','EBRD':'https://www.ebrd.com/home/what-we-do/projects.html','IRENA':'https://www.irena.org/Data','ENTSO-E':'https://transparency.entsoe.eu/','Copernicus':'https://drought.emergency.copernicus.eu/'}
out={}
for v,rows in M.items():
 out[v]=[]
 for n,w,s,k,status in rows:
  url=next((u for x,u in urls.items() if x in s),urls['Eurostat']);out[v].append({'name':n,'weight':w,'source':s,'url':url,'frequency':'Monthly / annual / event-driven','role':'Direct / leading / forward','key':k,'pipelineStatus':status,'treatment':'Validated source observation → normalised 0–100 → weighted contribution'})
 assert sum(x['weight'] for x in out[v])==100
pathlib.Path('public/data/indicator-methodology.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
